contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to call getTokens with a paid amount and assert invariant
    function run(uint256 payAmount) public payable {
        require(address(this).balance >= payAmount);

        // observe before-values via public getters
        uint256 before_totalDistributed = c.totalDistributed();
        uint256 before_totalRemaining = c.totalRemaining();
        uint256 before_balance_of_test = c.balanceOf(address(this));
        uint256 before_contract_eth = address(c).balance;

        bool reverted;
        // call getTokens by sending Ether to c (getTokens is public payable and also triggered by receive)
        try c.getTokens{value: payAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 after_totalDistributed = c.totalDistributed();
        uint256 after_totalRemaining = c.totalRemaining();
        uint256 after_balance_of_test = c.balanceOf(address(this));
        uint256 after_contract_eth = address(c).balance;

        // If call reverted, nothing is required about state changes other than that balances didn't increase
        // General rule: if not reverted then (a) contract's ether increased by exactly payAmount, and
        // (b) the token balance of this test holder increased by some amount d, and totalDistributed increased by same d,
        // and totalRemaining decreased by same d, and d <= before_totalRemaining.

        assert(
            reverted || (
                after_contract_eth == before_contract_eth + payAmount
                && after_totalDistributed >= before_totalDistributed
                && before_totalRemaining >= after_totalRemaining
                && (after_totalDistributed - before_totalDistributed) == (before_totalRemaining - after_totalRemaining)
                && (after_balance_of_test - before_balance_of_test) == (after_totalDistributed - before_totalDistributed)
                && (after_totalDistributed - before_totalDistributed) <= before_totalRemaining
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call transfer on c from this contract. The rule: if transfer succeeds then
    // - totalSupply does not change
    // - sender's balance decreases by _amount and recipient's balance increases by _amount
    // If transfer reverts then the reverted flag is true. The assert encodes that exactly one of
    // these holds for all inputs.
    function run(address to, uint256 amount) public payable {
        require(to != address(0)); // transfer would require non-zero destination

        // Observe pre-state
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecipientBal = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecipientBal = c.balanceOf(to);

        // If not reverted then the balances must have moved by exactly amount and totalSupply unchanged.
        // If reverted then nothing is required about balances (call didn't succeed).
        assert(reverted || (
            afterTotalSupply == beforeTotalSupply
            && afterSenderBal + amount == beforeSenderBal
            && afterRecipientBal == beforeRecipientBal + amount
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single-call simple property: for non-zero recipient and amount within sender balance range,
    // transfer either reverts or effects exact balance movement and preserves totalSupply.
    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(to);

        // Bound amount so that if transfer succeeds it is expected to be allowed by balance
        require(amount <= beforeSender);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterRecipient = c.balanceOf(to);

        // Exactly one simple comparison as the final assert: if not reverted then balances moved by amount and totalSupply unchanged.
        assert(reverted || (
            afterTotalSupply == beforeTotalSupply
            && afterSender + amount == beforeSender
            && afterRecipient == beforeRecipient + amount
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function testing approve behaviour
    function run(address spender, uint256 value) public payable {
        require(spender != address(0));

        bool reverted;
        try c.approve(spender, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 observed = c.allowance(address(this), spender);

        // If the call did not revert then the allowance must equal the requested value.
        assert(reverted || observed == value);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt transferFrom and assert the invariant
    function run(address from, address to, uint256 amt) public payable {
        require(address(this) != address(0));

        // observe before values
        uint256 before_totalSupply = c.totalSupply();
        uint256 before_from = c.balanceOf(from);
        uint256 before_to = c.balanceOf(to);
        uint256 before_allowance = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, to, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after_totalSupply = c.totalSupply();
        uint256 after_from = c.balanceOf(from);
        uint256 after_to = c.balanceOf(to);
        uint256 after_allowance = c.allowance(from, address(this));

        // If call succeeded then: totalSupply unchanged, from decreased by x, to increased by x,
        // and allowance decreased by x (unless it underflowed which would have caused revert).
        // If call reverted then no state change is required. Assert that either reverted is true
        // or the observed numeric relationships hold.
        assert(
            reverted
            || (
                after_totalSupply == before_totalSupply
                && before_from >= after_from
                && after_to >= before_to
                && (before_from - after_from) == (after_to - before_to)
                && (before_allowance >= after_allowance)
                && (before_allowance - after_allowance) == (before_from - after_from)
            )
        );
    }

    receive() external payable { }
}
